<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import * as store from './store';
import {isSolved,sameTable,shuffleTiles,tileSignatures} from './play';
import type {Artwork} from './store';
import {SERVER_WORLD,newUploadKey,sendPhoto} from './server/upload';
const props=defineProps<{artworks:Artwork[];childAge:number}>();
const emit=defineEmits<{close:[];saved:[id:string]}>();
type Game='menu'|'draw'|'pairs'|'puzzle';
const game=ref<Game>('menu'),msg=ref(''),busy=ref(false),confirmLeave=ref(false),celebrate=ref(false);
const canvas=ref<HTMLCanvasElement|null>(null),color=ref('#3c80d1'),width=ref(10),turn=ref(1);
type Stroke={color:string;width:number;points:Array<[number,number]>};
const strokes=ref<Stroke[]>([]);let drawing=false;let saveId=store.newId();const uploadKey=newUploadKey(); // 다시 시도해도 작품이 두 번 생기지 않게 같은 값을 쓴다
// 그리기 초안(§2-11): 획을 끝낼 때·되돌릴 때·차례를 넘길 때 가족별로 기기에 남긴다. 쓰기는 순서대로 이어 붙여 보관 직전에 모두 끝낸다.
const restored=ref(false),draftWarn=ref(false);let pendingDraft:Promise<void>=Promise.resolve(),saved=false;
function persistDraft(){const snap={id:saveId,strokes:strokes.value,turn:turn.value,updatedAt:Date.now()};pendingDraft=pendingDraft.then(async()=>{if(saved)return;try{if(snap.strokes.length)await store.saveDraft(snap);else await store.deleteDraft();draftWarn.value=false;}catch{draftWarn.value=true;}});return pendingDraft;}
onMounted(async()=>{try{const d=await store.getDraft();if(d?.strokes.length&&!strokes.value.length){saveId=d.id;strokes.value=d.strokes;turn.value=Math.max(1,d.turn|0);restored.value=true;redraw();}}catch{/* 초안을 못 읽어도 새로 그릴 수 있다 */}});
const colors=['#343342','#3c80d1','#e35870','#ecb537','#58a47b','#906ac4','#ffffff'];
const urls=new Map<string,string>();
function image(a:Artwork){let u=urls.get(a.id);if(!u){u=URL.createObjectURL(a.display);urls.set(a.id,u);}return u;}
function redraw(){const c=canvas.value;if(!c)return;const ctx=c.getContext('2d')!;ctx.fillStyle='#fffdf5';ctx.fillRect(0,0,c.width,c.height);for(const s of strokes.value){ctx.strokeStyle=ctx.fillStyle=s.color;ctx.lineWidth=s.width;ctx.lineCap=ctx.lineJoin='round';ctx.beginPath();s.points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();if(s.points.length===1){ctx.beginPath();ctx.arc(...s.points[0]!,s.width/2,0,Math.PI*2);ctx.fill();}}}
function point(e:PointerEvent):[number,number]{const c=canvas.value!,r=c.getBoundingClientRect();return [Math.max(0,Math.min(640,(e.clientX-r.left)/r.width*640)),Math.max(0,Math.min(480,(e.clientY-r.top)/r.height*480))];}
function start(e:PointerEvent){if(busy.value||e.button>0)return;drawing=true;canvas.value!.setPointerCapture(e.pointerId);strokes.value.push({color:color.value,width:width.value,points:[point(e)]});redraw();}
function move(e:PointerEvent){if(!drawing||busy.value)return;strokes.value.at(-1)!.points.push(point(e));redraw();}
function end(){if(!drawing)return;drawing=false;void persistDraft();}
function undo(){if(busy.value)return;strokes.value.pop();redraw();void persistDraft();}
function nextTurn(){turn.value++;void persistDraft();}
async function discard(){if(busy.value)return;saved=true;await pendingDraft;try{await store.deleteDraft();}catch{/* 지우지 못한 초안은 다음에 다시 열린다 */}emit('close');}
function leave(){if(busy.value)return;if(strokes.value.length){confirmLeave.value=true;return;}emit('close');}
defineExpose({requestClose:leave});
function choose(g:Game){game.value=g;msg.value='';celebrate.value=false;confirmLeave.value=false;clearTimeout(timer);if(g==='pairs')resetPairs();if(g==='puzzle')resetPuzzle();}
watch(game,async g=>{if(g==='draw'){await nextTick();redraw();}});
async function saveDrawing(){if(!strokes.value.length||busy.value)return;busy.value=true;msg.value='';try{await pendingDraft;const blob=await new Promise<Blob>((resolve,reject)=>canvas.value!.toBlob(b=>b?resolve(b):reject(new Error('canvas')),'image/png'));if(SERVER_WORLD){const r=await sendPhoto(new File([blob],'함께 그린 그림.png',{type:'image/png'}),uploadKey);if(!r.ok){msg.value=r.reason;return;}saved=true;try{await store.deleteDraft();}catch{/* 지우지 못한 초안은 다음에 다시 열린다 */}emit('saved',r.id);return;}const p=await store.processImage(blob,false),all=await store.listArtworks();await store.saveArtworkAndRoom({id:saveId,no:all.reduce((n,a)=>Math.max(n,a.no),0)+1,title:'함께 그린 그림',kind:'drawing',subject:'etc',material:'디지털 그림',age:props.childAge,madeOn:'',words:'',original:blob,display:p.display,cutout:null,cutoutState:'pending',sample:false,createdAt:Date.now()},{clearDraft:true});saved=true;emit('saved',saveId);}catch{msg.value='저장하지 못했어요. 그림은 남아 있어요. 다시 눌러 주세요';}finally{busy.value=false;}}
function shuffled<T>(a:T[]){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j]!,b[i]!];}return b;}
const pairCount=ref(4),cards=ref<Array<{id:string;art:Artwork}>>([]),flipped=ref<number[]>([]),matched=ref<string[]>([]),pairTurn=ref(1);let timer:ReturnType<typeof setTimeout>;
const enough=computed(()=>props.artworks.length>=pairCount.value);
function resetPairs(){clearTimeout(timer);flipped.value=[];matched.value=[];pairTurn.value=1;celebrate.value=false;const arts=shuffled(props.artworks).slice(0,pairCount.value);cards.value=shuffled(arts.flatMap(art=>[{id:art.id+'a',art},{id:art.id+'b',art}]));}
function flip(i:number){const c=cards.value[i];if(!c||flipped.value.length>=2||flipped.value.includes(i)||matched.value.includes(c.art.id))return;flipped.value.push(i);if(flipped.value.length===2){const [a,b]=flipped.value;if(cards.value[a!]!.art.id===cards.value[b!]!.art.id){matched.value.push(c.art.id);flipped.value=[];if(matched.value.length===pairCount.value)celebrate.value=true;}else timer=setTimeout(()=>{flipped.value=[];pairTurn.value=pairTurn.value===1?2:1;},900);}}
const puzzleArt=ref(props.artworks.at(-1)?.id??''),size=ref(2),tiles=ref<number[]>([]),selected=ref<number|null>(null),showOriginal=ref(false);
// 퍼즐 판(§2-11): 작품의 가로세로비를 그대로 쓰고, 모양이 같은 조각은 서로 바꿔도 맞은 자리로 본다.
const ratio=ref(1),same=ref<boolean[][]>([]),puzzleMsg=ref('');let puzzleToken=0;
const puzzle=computed(()=>props.artworks.find(a=>a.id===puzzleArt.value)),solved=computed(()=>isSolved(tiles.value,same.value));
async function signatures(url:string,n:number){const img=new Image();img.src=url;await img.decode();const w0=img.naturalWidth||1,h0=img.naturalHeight||1,k=Math.min(1,240/Math.max(w0,h0)),w=Math.max(n,Math.round(w0*k)),h=Math.max(n,Math.round(h0*k));const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');if(!ctx)return {ratio:w0/h0,sigs:null};ctx.drawImage(img,0,0,w,h);return {ratio:w0/h0,sigs:tileSignatures(ctx.getImageData(0,0,w,h).data,w,h,n)};}
async function resetPuzzle(){const token=++puzzleToken,a=puzzle.value,n=size.value;tiles.value=[];selected.value=null;showOriginal.value=false;celebrate.value=false;puzzleMsg.value='';if(!a)return;let info:{ratio:number;sigs:number[][]|null}={ratio:1,sigs:null};try{info=await signatures(image(a),n);}catch{/* 그림을 읽지 못하면 조각 번호로만 판정한다 */}if(token!==puzzleToken)return;ratio.value=Number.isFinite(info.ratio)&&info.ratio>0?info.ratio:1;same.value=sameTable(info.sigs,n*n);const order=shuffleTiles(n*n,same.value);if(!order){puzzleMsg.value='같은 모양 조각이 많아 퍼즐로 놀기 어려워요. 다른 작품을 골라 주세요';return;}tiles.value=order;}
function tile(i:number){if(solved.value)return;if(selected.value===null){selected.value=i;return;}if(selected.value===i){selected.value=null;return;}const a=selected.value;[tiles.value[a],tiles.value[i]]=[tiles.value[i]!,tiles.value[a]!];selected.value=null;if(solved.value)celebrate.value=true;}
watch(puzzleArt,()=>{if(game.value==='puzzle')void resetPuzzle();});
const celebrateEl=ref<HTMLElement|null>(null);
watch(celebrate,async on=>{if(!on)return;await nextTick();const el=celebrateEl.value;if(!el)return;const calm=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;el.scrollIntoView?.({block:'nearest',behavior:calm?'auto':'smooth'});el.focus({preventScroll:true});});
function tileStyle(v:number){return {backgroundImage:`url("${puzzle.value?image(puzzle.value):''}")`,backgroundSize:`${size.value*100}% ${size.value*100}%`,backgroundPosition:`${v%size.value/(size.value-1)*100}% ${Math.floor(v/size.value)/(size.value-1)*100}%`};}
onBeforeUnmount(()=>{clearTimeout(timer);for(const u of urls.values())URL.revokeObjectURL(u);});
</script>
<template>
 <div class="sheet w-play" role="dialog" aria-modal="true" aria-label="함께 놀기">
  <div class="w-play-card g-panel">
   <header><div><p class="w-eyebrow">우리 작품으로 만드는 시간</p><h2>{{game==='menu'?'함께 놀기':game==='draw'?'함께 그리기':game==='pairs'?'우리 작품 짝 찾기':'작품 퍼즐'}}</h2></div><button class="g-btn" :disabled="busy" @click="leave">닫기</button></header>
   <template v-if="game==='menu'">
    <p>혼자 해도, 가족과 함께 해도 좋아요. 같은 화면에서 번갈아 놀아요.</p>
    <div class="w-game-menu"><button @click="choose('draw')"><span>✎</span><strong>함께 그리기</strong><small>{{restored?'그리던 그림을 이어서 그려요':'선을 하나씩 더해 우리 그림을 만들어요'}}</small></button><button @click="choose('pairs')"><span>▧</span><strong>우리 작품 짝 찾기</strong><small>같은 작품 두 장을 함께 찾아요</small></button><button @click="choose('puzzle')"><span>▦</span><strong>작품 퍼즐</strong><small>우리 작품을 다시 맞춰 봐요</small></button></div>
   </template>
   <template v-if="game==='draw'">
    <p class="w-turn" :key="turn">{{turn}}번째 차례예요. 다 그리면 다음 사람에게 넘겨요.</p>
    <p v-if="restored" class="w-draft-note" role="status">그리던 그림을 다시 불러왔어요.</p>
    <p v-if="draftWarn" class="w-draft-note w-draft-warn" role="alert">이 기기에 임시로 남기지 못했어요. 보관하기 전에 창을 닫으면 사라질 수 있어요.</p>
    <div class="w-draw-tools"><button v-for="c in colors" :key="c" :style="{background:c}" class="w-color" :aria-label="'그림 색 '+c" :aria-pressed="color===c" :disabled="busy" @click="color=c"/><label>선 굵기<input v-model.number="width" type="range" min="3" max="30" :disabled="busy" /></label><button class="g-btn" :disabled="!strokes.length||busy" @click="undo">한 번 되돌리기</button></div>
    <canvas ref="canvas" width="640" height="480" class="w-draw-canvas" aria-label="함께 그리는 도화지" @pointerdown.prevent="start" @pointermove.prevent="move" @pointerup="end" @pointercancel="end" />
    <div class="w-play-actions"><button class="g-btn" :disabled="busy" @click="nextTurn">다음 사람 차례</button><button class="g-btn g-btn--primary" :disabled="!strokes.length||busy" @click="saveDrawing">{{busy?'그림을 보관하는 중…':'우리 그림 보관하기'}}</button></div>
   </template>
   <template v-if="game==='pairs'">
    <div class="w-play-actions"><button class="g-btn" :aria-pressed="pairCount===4" @click="pairCount=4;resetPairs()">4쌍</button><button class="g-btn" :aria-pressed="pairCount===6" @click="pairCount=6;resetPairs()">6쌍</button><button class="g-btn" @click="resetPairs">다시 섞기</button></div>
    <template v-if="enough"><p class="w-turn" :key="pairTurn">{{pairTurn}}번 사람 차례 · {{matched.length}} / {{pairCount}}쌍을 찾았어요</p><div class="w-pair-grid"><button v-for="(c,i) in cards" :key="c.id" class="w-pair" :class="{'w-open':flipped.includes(i)||matched.includes(c.art.id),'w-matched':matched.includes(c.art.id)}" :disabled="matched.includes(c.art.id)" :aria-label="flipped.includes(i)||matched.includes(c.art.id)?(c.art.title||'작품'):(i+1)+'번 카드 뒤집기'" @click="flip(i)"><span class="w-card-back">✦</span><img v-if="flipped.includes(i)||matched.includes(c.art.id)" :src="image(c.art)" alt="" /></button></div></template>
    <p v-else>작품을 {{pairCount}}점 보관하면 이 놀이를 할 수 있어요. 지금은 함께 그림을 만들어 볼까요? <button class="g-btn" @click="choose('draw')">함께 그리기</button></p>
   </template>
   <template v-if="game==='puzzle'">
    <template v-if="puzzle"><div class="w-play-actions"><label>맞출 작품<select v-model="puzzleArt"><option v-for="a in artworks" :key="a.id" :value="a.id">{{a.title||'우리 작품'}}</option></select></label><button class="g-btn" :aria-pressed="size===2" @click="size=2;resetPuzzle()">4조각</button><button class="g-btn" :aria-pressed="size===3" @click="size=3;resetPuzzle()">9조각</button><button class="g-btn" :aria-pressed="showOriginal" @click="showOriginal=!showOriginal">원본 보기</button></div><p>바꿀 조각 두 개를 눌러요. 시간 제한은 없어요.</p><img v-if="showOriginal" class="w-puzzle-original" :src="image(puzzle)" alt="완성할 작품"/><p v-if="puzzleMsg" role="status">{{puzzleMsg}}</p><div v-if="tiles.length" class="w-puzzle" :style="{gridTemplateColumns:`repeat(${size},1fr)`,gridTemplateRows:`repeat(${size},1fr)`,'--ar':ratio}"><button v-for="(v,i) in tiles" :key="i" :style="tileStyle(v)" :class="{'w-selected':selected===i,'w-correct':solved}" :aria-label="(i+1)+'번 자리, 그림 조각 '+(v+1)" :aria-pressed="selected===i" @click="tile(i)" /></div><button class="g-btn" @click="resetPuzzle">다시 섞기</button></template><p v-else>작품을 하나 남기면 퍼즐로 놀 수 있어요. <button class="g-btn" @click="choose('draw')">함께 그리기</button></p>
   </template>
   <div v-if="celebrate" ref="celebrateEl" class="w-celebrate" role="status" tabindex="-1"><span v-for="i in 16" :key="i" :style="{'--i':i}" aria-hidden="true">✦</span><strong>함께 해냈어요</strong><p>우리 작품을 다시 한번 바라봐요.</p></div>
   <p v-if="msg" role="alert">{{msg}}</p>
   <button v-if="game!=='menu'" class="g-btn w-back" :disabled="busy" @click="choose('menu')">다른 놀이</button>
   <section v-if="confirmLeave" class="w-leave" role="alert"><p>아직 보관하지 않은 그림이 있어요.</p><button class="g-btn g-btn--primary" :disabled="busy" @click="choose('draw')">계속 그리기</button><button class="g-btn" :disabled="busy" @click="discard">보관하지 않고 닫기</button></section>
  </div>
 </div>
</template>
<style scoped>
.w-play{position:absolute;inset:0;z-index:22;display:grid;place-items:center;padding:12px;background:#263c5266;backdrop-filter:blur(7px)}.w-play-card{width:min(780px,100%);max-height:94dvh;overflow:auto;padding:22px;display:grid;gap:14px;background:#fffdf4;animation:w-arrive .28s ease-out}.w-play header{display:flex;justify-content:space-between;align-items:center;gap:12px}.w-play h2{margin:0;font-size:25px}.w-play p{margin:0;line-height:1.5}.w-eyebrow{font-size:12px;color:#657360}.w-game-menu{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.w-game-menu button{border:2px solid #e1d9be;border-radius:20px;background:#eff5e5;padding:22px 12px;display:grid;gap:12px;text-align:left;font:inherit;color:#304735;box-shadow:0 5px #d0dabb;transition:transform .16s}.w-game-menu button:nth-child(2){background:#e9f0fc;box-shadow:0 5px #becfe2;color:#344e6f}.w-game-menu button:nth-child(3){background:#f9e8ed;box-shadow:0 5px #e2becb;color:#784258}.w-game-menu span{font-size:50px;line-height:1}.w-game-menu strong{font-size:20px}.w-game-menu small{line-height:1.5}.w-play button{cursor:pointer}.w-play button:active:not(:disabled){transform:translateY(3px) scale(.97)}.w-play button:focus-visible{outline:3px solid #368bd3;outline-offset:3px}.w-play button:disabled{cursor:default;opacity:.6}.w-draw-tools,.w-play-actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.w-color{width:38px;height:38px;border:3px solid #d1c9ba;border-radius:50%}.w-color[aria-pressed=true]{outline:3px solid #263c52;outline-offset:2px}.w-draw-tools label{display:grid;font-size:13px}.w-draw-canvas{width:100%;aspect-ratio:4/3;touch-action:none;border:2px solid #dbd3bd;border-radius:12px;box-shadow:0 6px 18px #544b3a15;background:#fffdf5}.w-turn{padding:10px 14px;border-radius:12px;background:#eef4df;color:#3e5730;animation:w-turn .3s ease-out}.w-pair-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.w-pair{position:relative;aspect-ratio:1.15;border:3px solid #d9c99d;border-radius:14px;background:#62859a;overflow:hidden;transition:background .2s,transform .3s;min-height:66px}.w-card-back{font-size:42px;color:#fff7db}.w-pair img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#fffdf5;animation:w-flip .24s ease-out}.w-pair.w-matched{opacity:1;border-color:#5cae6e;animation:w-match .38s ease-out}.w-play select{min-height:44px;max-width:250px;font:inherit;border:1px solid #d5c6a7;border-radius:8px;padding:6px;background:white}.w-puzzle{display:grid;gap:4px;width:min(440px,100%,calc(56dvh * var(--ar,1)));aspect-ratio:var(--ar,1);justify-self:center}.w-draft-note{font-size:14px;color:#4c6340}.w-draft-warn{color:#8a3d22}.w-celebrate:focus{outline:none}.w-puzzle button{min-width:0;border:2px solid #f9efd4;border-radius:7px;background-repeat:no-repeat;transition:box-shadow .16s,transform .16s}.w-puzzle .w-selected{outline:4px solid #3c80d1;outline-offset:-4px;transform:scale(.93)}.w-puzzle .w-correct{border-color:#60aa73;animation:w-match .4s ease-out}.w-puzzle-original{width:min(220px,60%);max-height:150px;object-fit:contain;justify-self:center}.w-celebrate{position:relative;text-align:center;overflow:hidden;min-height:100px;padding:20px;background:#ecf4d9;border-radius:20px;animation:w-match .4s ease-out}.w-celebrate strong{font-size:28px;color:#426b37}.w-celebrate span{position:absolute;left:calc(var(--i)*6%);top:0;color:#d69e32;animation:w-confetti 1.7s ease-out both;animation-delay:calc(var(--i)*.035s);pointer-events:none}.w-back{justify-self:start}.w-leave{padding:16px;border:2px solid #d9a45c;border-radius:16px;display:flex;flex-wrap:wrap;gap:10px}.w-leave p{flex-basis:100%}
@keyframes w-arrive{from{opacity:0;transform:translateY(16px) scale(.98)}to{opacity:1;transform:none}}@keyframes w-turn{from{transform:translateX(-8px);opacity:.5}to{transform:none;opacity:1}}@keyframes w-flip{from{transform:rotateY(90deg)}to{transform:rotateY(0)}}@keyframes w-match{0%{transform:scale(.96)}55%{transform:scale(1.04)}100%{transform:scale(1)}}@keyframes w-confetti{from{transform:translateY(-12px) rotate(0);opacity:1}to{transform:translateY(115px) rotate(160deg);opacity:0}}
@media(max-width:600px){.w-play-card{padding:16px}.w-game-menu{grid-template-columns:1fr}.w-game-menu button{grid-template-columns:50px 1fr;padding:14px;gap:4px 12px}.w-game-menu span{grid-row:span 2;font-size:42px}.w-game-menu strong{font-size:19px}.w-play h2{font-size:22px}.w-color{width:34px;height:34px}.w-pair-grid{gap:6px}}
@media(prefers-reduced-motion:reduce){.w-play *{animation:none!important;transition:none!important}}
</style>
